`+t.markup}return e}function __fixtureRules(e){var n={};function t(u){for(var g=analyze(u,e),h=0;h<g.bases.length;h++){var x=__split(renderBase(g.bases[h],e)).rules;for(var b in x)n[b]=x[b]}}function s(u,g){return{view_name:"v_fixture_"+u,ddl:g}}var r=`SELECT
  a,
  b
FROM t_SUF
WHERE x = 1`,o=`SELECT
  a,
  c.b
FROM t_SUF
